package com.fooddelivery.restaurant; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import java.math.BigDecimal; @Configuration public class SeedData{@Bean CommandLineRunner seed(RestaurantRepository rr,MenuItemRepository mr){return a->{if(rr.count()>0)return;var r=new Restaurant();r.setName("Spice Garden");r.setDescription("Indian comfort food and biryani");r.setAddress("Pune, Maharashtra");r.setImageUrl("https://images.unsplash.com/photo-1517248135467-4c7edcad34c4");rr.save(r);Object[][] x={{"Chicken Biryani","Aromatic basmati biryani",299},{"Paneer Tikka","Char-grilled paneer",229},{"Butter Naan","Tandoor baked naan",59},{"Masala Dosa","Crispy dosa with chutney",149}};for(Object[] i:x){var m=new MenuItem();m.setName((String)i[0]);m.setDescription((String)i[1]);m.setPrice(BigDecimal.valueOf((Integer)i[2]));m.setRestaurantId(r.getId());mr.save(m);}};}}